#!/bin/sh
# Build faction_switch.pack (vanilla Rome II, main_rome). usage: sh tools/build_pack.sh   (from the project folder)
# Contents:
#   campaigns/main_rome/scripting.lua  CA's vanilla file (work/vanilla, from data_rome2.pack) + a tail that loads ours
#   lua_scripts/fs_switch.lua          pack_src
#   lua_scripts/fs_factions.lua        generated by tools/uibuild_fs.py
#   ui/campaign ui/campaign_tactical_map  vanilla layout + our button and window (tools/uibuild_fs.py, etwng xml2ui);
#                                      Lua moves them under menu_bar
# Not copied into the game. Replaces 2 game files: other mods that replace them conflict (DeI: scripting.lua).
# Consul Scriptum replaces menu_bar and all_scripted.lua: no conflict.
set -e
P=/f/ROME2/Projects/faction-switch
R="/f/ROME2/_TOOLS/Rusted PackFile Manager/rpfm_cli.exe"
D=/f/ROME2/ConsulScriptum/.deps
export PATH="$D/ruby/bin:$PATH" GEM_HOME="$D/ruby/lib/ruby/gems/3.4.0" GEM_PATH="$D/ruby/lib/ruby/gems/3.4.0"
cd "$P"
OUT=$(cygpath -m "$P/build/faction_switch.pack")
python tools/uibuild_fs.py
rm -rf build/stage; mkdir -p "build/stage/campaigns/main_rome" build/stage/lua_scripts "build/stage/ui/campaign ui"
V=work/vanilla/campaigns/main_rome/scripting.lua
grep -q 'scripting.SetCampaign("main_rome")' "$V"
{ cat "$V"; printf '\r\n\r\n'; cat pack_src/scripting_tail.lua; } > build/stage/campaigns/main_rome/scripting.lua
cp pack_src/lua_scripts/fs_switch.lua build/stage/lua_scripts/
cp build/fs_factions.lua build/stage/lua_scripts/
for f in build/stage/lua_scripts/*.lua build/stage/campaigns/main_rome/scripting.lua; do "$D/lua/luac5.1.exe" -p "$f"; done
ruby "$D/etwng/ui/bin/xml2ui" build/campaign_tactical_map_fs.xml "build/stage/ui/campaign ui/campaign_tactical_map"
rm -f "$OUT"
"$R" --game rome_2 pack create --pack-path "$OUT" >/dev/null 2>&1
"$R" --game rome_2 pack add --pack-path "$OUT" -F "$(cygpath -m "$P/build/stage")" >/dev/null 2>&1
"$R" --game rome_2 pack list -p "$OUT" 2>/dev/null | grep -v INFO
ls -la build/faction_switch.pack; sha256sum build/faction_switch.pack | cut -c1-12
